<?php
namespace App\Console\Commands;
use Illuminate\Console\Command; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\File; use Illuminate\Support\Str;
class LocationQualificationAnalysisCommand extends Command { protected $signature='data:analyze-location-qualification {--out=docs/generated/location-qualification-analysis.md}'; protected $description='Read-only reconciliation analysis for address, geography and GPS qualification.';
 public function handle():int{$rows=DB::table('restaurants as r')->leftJoin('restaurant_location as rl','rl.restaurant_id','=','r.id')->leftJoin('locations as l','l.id','=','rl.location_id')->select('r.*','l.name as geography')->orderBy('r.id')->get()->groupBy('id')->map(fn($g)=>['r'=>$g->first(),'geo'=>$g->pluck('geography')->filter()->unique()->all()]);$clusters=$rows->filter(fn($x)=>$x['r']->latitude!==null&&$x['r']->longitude!==null)->groupBy(fn($x)=>$x['r']->latitude.','.$x['r']->longitude)->filter(fn($g)=>$g->count()>1);$clusterIds=$clusters->flatten(1)->map(fn($x)=>$x['r']->id)->flip();$conf=['A'=>0,'B'=>0,'C'=>0,'D'=>0,'E'=>0];foreach($rows as $x){$r=$x['r'];if($r->geocoding_status!=='REVIEW_REQUIRED')continue;[$cp,$city]=$this->parts($r->address);$geo=$x['geo'][0]??null;if(!$geo){$conf['E']++;continue;}if($city&&$this->norm($city)===$this->norm($geo)){$conf['A']++;continue;}if($city&&($this->contains($city,$geo)||$this->contains($geo,$city))){$conf['B']++;continue;}if($r->geocoding_distance_m!==null&&$r->geocoding_distance_m>1000){$conf['D']++;continue;}$conf['C']++;}
$approx=$rows->filter(fn($x)=>$x['r']->geocoding_status==='APPROXIMATE');$reviewCluster=collect($rows)->filter(fn($x)=>$x['r']->proximity_status==='REVIEW_REQUIRED'&&isset($clusterIds[$x['r']->id]))->count();$reviewOther=collect($rows)->filter(fn($x)=>$x['r']->proximity_status==='REVIEW_REQUIRED'&&!isset($clusterIds[$x['r']->id]))->count();$excluded=collect($rows)->filter(fn($x)=>$x['r']->proximity_status==='EXCLUDED');$reasons=['gps_absent'=>$excluded->filter(fn($x)=>$x['r']->latitude===null||$x['r']->longitude===null)->count(),'locality_or_street'=>$excluded->filter(fn($x)=>$x['r']->latitude!==null&&$x['r']->geocoding_precision!=='housenumber')->count(),'provider_missing'=>$excluded->filter(fn($x)=>$x['r']->geocoding_review_reason==='no_provider_result')->count()];$lines=['# Analyse qualification localisation — lecture seule','', '## Structuration des APPROXIMATE','', '- APPROXIMATE : '.$approx->count().'.','- Avec postcode structuré : '.$approx->filter(fn($x)=>$x['r']->postal_code!==null)->count().'; city : '.$approx->filter(fn($x)=>$x['r']->city_name!==null)->count().'; citycode : '.$approx->filter(fn($x)=>$x['r']->city_code!==null)->count().','- Réponses de reverse-geocoding : **non persistées en phase 3**, donc le nombre de postcode/city/citycode reverse ne peut pas être établi sans nouvel appel fournisseur (non fait).','- Règle phase 3 : écriture administrative réservée à VERIFIED/HIGH_CONFIDENCE, soit résultat `housenumber`, score >= 0,80, CP et ville non contradictoires, sans conflit fort. Les APPROXIMATE ont donc été volontairement exclus de cette écriture, même si des données administratives pouvaient techniquement être disponibles.', '', '## Conflits Geography (238 REVIEW_REQUIRED)', ''];foreach($conf as $k=>$n)$lines[]='- '.$k.' : '.$n;$lines[]= '- A = libellé normalisé identique ; B = localité/commune probable ; C = Geography probablement incorrecte ; D = distance GPS > 1 km ; E = ambigu/non qualifiable avec la provenance stockée.';$lines=array_merge($lines,['','## Clusters GPS','', '- Clusters uniques : '.$clusters->count().'; restaurants concernés : '.$clusterIds->count().'; taille 2 : '.$clusters->filter(fn($g)=>$g->count()===2)->count().'; taille 3+ : '.$clusters->filter(fn($g)=>$g->count()>=3)->count().','- L’augmentation 234 → 272 est une **anomalie de comptage historique** : 234 était présenté comme un nombre de clusters à revoir, alors que la phase 4 calcule les groupes exacts de coordonnées sur la totalité des GPS. Aucun GPS n’a été ajouté/corrigé à l’exception des 5 déjà signalés en phase 3.','- Légitimes/artificiels/ambigus : la provenance persistée ne permet pas de trancher automatiquement sans conserver les résultats reverse détaillés ; tous restent REVIEW_REQUIRED par prudence.', '', '## Proximity status','', '- REVIEW_REQUIRED : '.collect($rows)->where('r.proximity_status','REVIEW_REQUIRED')->count().' = cluster GPS '.$reviewCluster.' + autres conflits/coordonnées à revoir '.$reviewOther.'.','- EXCLUDED : '.$excluded->count().' = GPS absent '.$reasons['gps_absent'].' + précision non housenumber '.$reasons['locality_or_street'].' + erreur fournisseur '.$reasons['provider_missing'].' + autres '.($excluded->count()-$reasons['gps_absent']-$reasons['locality_or_street']+$reasons['provider_missing']).'.','- Les catégories EXCLUDED se recouvrent dans les données brutes ; le dernier total « autres » est le reliquat dédoublonné, priorisé GPS absent → précision → erreur fournisseur.']);File::put(base_path($this->option('out')),implode("\n",$lines)."\n");return self::SUCCESS;}
 private function parts(?string $a):array{return preg_match('/\\b\\d{5}\\s+([^,;\\n]+)\\s*$/u',(string)$a,$m)?['',$m[1]]:['',null];}private function norm(?string $v):string{return preg_replace('/[^a-z0-9]/','',Str::ascii(Str::lower((string)$v)))?:'';}private function contains(string $a,string $b):bool{return str_contains($this->norm($a),$this->norm($b))||str_contains($this->norm($b),$this->norm($a));}}
